INSERT INTO vehicle_variants VALUES
  ('ford-f-150-2024-xlt-5-5-ft-tub-swb', 'Ford', 'F-150', 2024, NULL, 'XLT', 'crew_cab', 'pickup_tub', NULL, '3.5L EcoBoost twin-turbo V6', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3697, 2462, 'Published kerb weight', 3315, 7365, 1565, 1977, 853, 'Manufacturer-published GVM minus kerb', 4500, NULL, 1700, 1650, NULL, 'ford-f150-my24-au', 'Official – prior model-year detailed sheet: XLT 5.5-ft tub (SWB)', 'source_verified', 0, 'OPTIMISTIC KERB: recorded basis is Ford Australia''s published Kerb Weight, which Ford defines across its Australian range as the lightest possible orderable combination of factory-fit equipment, so the payload is a best case. That definition is read from the Ranger brochure footnote rather than confirmed against the F-150 MY24 sheet itself; disclosed to the customer on the owner''s decision because under-disclosing an optimistic figure is the worse error. Confirm against the F-150 sheet footnote when a copy is to hand. Load body as published: 5.5-ft tub (SWB). Current Australian range is confirmed, but detailed masses and dimensions are from Ford Australia''s official MY24 engineering sheet. Load-floor height 921 mm; top-of-tub length 1662 mm. Tub-compatible camper only unless engineered tray conversion is verified.'),
