  ('ram-2500-2025-laramie-cummins-high-output-6-4-tub', 'RAM', '2500', 2025, NULL, 'Laramie Cummins High Output', 'crew_cab', 'pickup_tub', '4x4 part-time', '6.7L Cummins high-output turbo-diesel', 'ZF TorqueFlite 8AP1075 8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3785, 3710, 'Published kerb weight', 4495, 12750, 2608, 2721, 785, 'GVM minus certified kerb', 4500, 450, 1937, 1687, NULL, 'ram-2500-3500-au', 'Official current brochure: Laramie Cummins High Output 6''4" tub', 'source_verified', 0, 'Load body as published: 6''4" tub. Manufacturer drivetrain description: Part-time 4x4 with low range. Ball-coupled braked towing is 4,500 kg with genuine RAM 70 mm hardware. Up to 8,000 kg gooseneck towing is separately specified with genuine hardware and air-braked trailer; verify all fitted labels. Tub-compatible camper only unless engineered tray conversion is verified.'),
  ('ram-3500-2025-laramie-cummins-high-output-6-4-tub', 'RAM', '3500', 2025, NULL, 'Laramie Cummins High Output', 'crew_cab', 'pickup_tub', '4x4 part-time', '6.7L Cummins high-output turbo-diesel', 'ZF TorqueFlite 8AP1075 8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3785, 3700, 'Published kerb weight', 5352, 14433, 2721, 3175, 1652, 'GVM minus certified kerb', 4500, 450, 1937, 1687, NULL, 'ram-2500-3500-au', 'Official current brochure: Laramie Cummins High Output 6''4" tub', 'source_verified', 0, 'Load body as published: 6''4" tub. Manufacturer drivetrain description: Part-time 4x4 with low range. Ball-coupled braked towing is 4,500 kg with genuine RAM 70 mm hardware. Up to 8,000 kg gooseneck towing is separately specified with genuine hardware and air-braked trailer; verify all fitted labels. Tub-compatible camper only unless engineered tray conversion is verified.'),
  ('ram-3500-2025-laramie-cummins-ho-4-495-kg-gvm-derate-6-4-tub', 'RAM', '3500', 2025, NULL, 'Laramie Cummins HO – 4,495 kg GVM derate', 'crew_cab', 'pickup_tub', '4x4 part-time', '6.7L Cummins high-output turbo-diesel', 'ZF TorqueFlite 8AP1075 8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3785, 3700, 'Published kerb weight', 4495, 14433, 2721, 3175, 795, 'GVM minus certified kerb', 4500, 450, 1937, 1687, NULL, 'ram-2500-3500-au', 'Official optional derated configuration: Laramie Cummins HO – 4,495 kg GVM derate 6''4" tub', 'source_verified', 0, 'Load body as published: 6''4" tub. Manufacturer drivetrain description: Part-time 4x4 with low range. Optional 4,495 kg GVM must be nominated before landing. The brochure does not explicitly state whether the standard 14,433 kg GCM changes after derating; confirm on the compliance plate. Ball-coupled braked towing is 4,500 kg with genuine RAM 70 mm hardware. Up to 8,000 kg gooseneck towing is separately specified with genuine hardware and air-braked trailer; verify all fitted labels. Tub-compatible camper only unless engineered tray conversion is verified.'),
  ('nissan-navara-2026-sl-pick-up-tub', 'Nissan', 'Navara', 2026, NULL, 'SL', 'dual_cab', 'pickup_tub', '4x4 part-time', '2.4L bi-turbo diesel', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3130, 2126, 'Published kerb weight', 3190, 6250, 1580, 2040, 1064, 'GVM minus kerb', 3500, NULL, 1555, 1545, NULL, 'nissan-navara-au', 'Official current specifications: SL Pick-up tub', 'source_verified', 0, 'Load body as published: Pick-up tub. Manufacturer drivetrain description: Easy Select part-time 4WD. AdBlue tank 17 L. Nissan''s public specification table does not state a towball maximum; use the towbar and vehicle labels. Tub-compatible camper only unless engineered tray conversion is verified.'),
