  ('mitsubishi-triton-26my-gls-double-pickup-4x4-1t', 'Mitsubishi', 'Triton', 2026, NULL, 'GLS', 'double_cab', 'pickup_tub', '4x4', '2.4L 4N16 bi-turbo diesel; 150 kW / 470 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3130, 2129, 'Published kerb mass', 3200, 6250, 1580, 2040, 1071, 'Published maximum payload; reconciles with GVM minus kerb mass', 3500, 350, NULL, NULL, NULL, 'mitsubishi-triton-26my-au', 'Dimensions and Weights: GLS double cab Pick-Up 4X4', 'source_verified', 0, 'Figures are for the standard GLS 1.0 t payload model. GLS Leather is 2,135 kg kerb and 1,065 kg payload. Tub-compatible camper only unless engineered tray conversion is verified.'),
  ('mitsubishi-triton-26my-gls-double-pickup-4x4-0-9t', 'Mitsubishi', 'Triton', 2026, NULL, 'GLS', 'double_cab', 'pickup_tub', '4x4', '2.4L 4N16 bi-turbo diesel; 150 kW / 470 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3130, 2129, 'Published kerb mass', 3080, 6250, 1580, 2040, 951, 'Published maximum payload; reconciles with GVM minus kerb mass', 3500, 350, NULL, NULL, NULL, 'mitsubishi-triton-26my-au', 'Dimensions and Weights: GLS double cab Pick-Up 4X4', 'source_verified', 0, 'The 0.9 t payload model carries a reduced 3,080 kg GVM on the same kerb mass. GLS Leather 0.9t is 2,135 kg kerb and 945 kg payload. Tub-compatible camper only unless engineered tray conversion is verified.'),
