  ('mitsubishi-triton-26my-gsr-double-pickup-4x4-1t', 'Mitsubishi', 'Triton', 2026, NULL, 'GSR', 'double_cab', 'pickup_tub', '4x4', '2.4L 4N16 bi-turbo diesel; 150 kW / 470 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3130, 2170, 'Published kerb mass', 3200, 6250, 1580, 2040, 1030, 'Published maximum payload; reconciles with GVM minus kerb mass', 3500, 350, NULL, NULL, NULL, 'mitsubishi-triton-26my-au', 'Dimensions and Weights: GSR double cab Pick-Up 4X4', 'source_verified', 0, 'Figures are for the 1.0 t payload model. Tub-compatible camper only unless engineered tray conversion is verified.'),
  ('mitsubishi-triton-26my-gsr-double-pickup-4x4-0-9t', 'Mitsubishi', 'Triton', 2026, NULL, 'GSR', 'double_cab', 'pickup_tub', '4x4', '2.4L 4N16 bi-turbo diesel; 150 kW / 470 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3130, 2170, 'Published kerb mass', 3080, 6250, 1580, 2040, 910, 'Published maximum payload; reconciles with GVM minus kerb mass', 3500, 350, NULL, NULL, NULL, 'mitsubishi-triton-26my-au', 'Dimensions and Weights: GSR double cab Pick-Up 4X4', 'source_verified', 0, 'The 0.9 t payload model carries a reduced 3,080 kg GVM on the same kerb mass. Lowest payload in the Triton range. Tub-compatible camper only unless engineered tray conversion is verified.');
