INSERT INTO heavy_overland_chassis (
INSERT INTO vehicle_model_coverage VALUES
  ('ford-ranger-super-duty', 'Ford', 'Ranger Super Duty', 'heavy_duty_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Full delivered-variant mass table captured from the official 2026.50MY specification sheet: all four cab types stored.'),
  ('toyota-hilux', 'Toyota', 'HiLux', 'midsize_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Core single/extra/double cab-chassis variants seeded.'),
  ('isuzu-dmax', 'Isuzu', 'D-MAX', 'midsize_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Core cab-chassis variants, axle ratings and accessory tray dimensions seeded.'),
  ('mazda-bt50', 'Mazda', 'BT-50', 'midsize_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Complete Australian range: 20 variants across single, Freestyle and dual cab in 4x2 and 4x4, cab-chassis stored with standard tray fitted. One conflict outstanding: Boss Pickup published payload does not reconcile with published kerb weight.'),
  ('mitsubishi-triton', 'Mitsubishi', 'Triton', 'midsize_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Complete 26MY range: 17 variants across 2WD and 4WD, single, club and double cab, cab-chassis and pick-up. Outstanding: Mitsubishi publishes an unexplained payload pair on the two single-cab-chassis columns.'),
  ('toyota-lc70', 'Toyota', 'LandCruiser 70', 'heavy_4wd_cab_chassis', 'current', 1, 'tray_cab_chassis', 'seeded', 'Automatic single/double cab variants seeded; manual combinations remain.'),
  ('kia-tasman', 'Kia', 'Tasman', 'midsize_ute', 'current', 1, 'tub_or_tray_conversion', 'seeded', 'MY26 dual-cab pickups plus five cab-chassis variants from the separate official cab-chassis brochure, verified directly. Kia states cab-chassis kerb and payload exclude tray bodies.'),
  ('ford-ranger', 'Ford', 'Ranger', 'midsize_ute', 'current', 1, 'tray_cab_chassis', 'seeded', 'Two model years recorded: 17 verified 2022MY variants, and 23 from the 2026.50MY brochure covering 4x2 and 4x4 in cab-chassis and pick-up. Outstanding: the 2026.50MY rows store the lightest-equipment kerb mass, so the heavier options figure must be added before customer exposure, and ford.com.au blocks automated retrieval.'),
  ('nissan-navara', 'Nissan', 'Navara', 'midsize_ute', 'current_or_transitioning', 2, 'tray_cab_chassis', 'seeded', 'All four grades of the all-new Navara seeded and verified directly against the official specifications page.'),
  ('gwm-cannon', 'GWM', 'Cannon', 'midsize_ute', 'current', 2, 'tray_cab_chassis', 'seeded', 'Seven 2026 grades seeded and verified directly against the official brochure, covering single cab and dual cab in tub and factory-alloy-tray bodies.'),
  ('gwm-cannon-alpha', 'GWM', 'Cannon Alpha', 'large_ute', 'current', 2, 'tub_or_tray_conversion', 'partially_seeded', 'Five grades seeded and verified directly against the official brochure, including HEV and PHEV. Outstanding: two 3.0 turbo-diesel grades are listed without a mass table.'),
  ('kgm-musso', 'KGM', 'Musso', 'midsize_ute', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'Six MY26 variants seeded and verified directly. The previously unattributed 880 kg and 1,010 kg payload configurations are Musso XLV variants, resolving the earlier mapping gap.'),
  ('kgm-musso-xlv', 'KGM', 'Musso XLV', 'midsize_ute', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'Six MY26 variants seeded and verified directly. The previously unattributed 880 kg and 1,010 kg payload configurations are Musso XLV variants, resolving the earlier mapping gap.'),
  ('vw-amarok', 'Volkswagen', 'Amarok', 'midsize_ute', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'Seven MY25 grades seeded and verified directly against the official brochure. Tub-only in the normal Australian range. Volkswagen derives its published payload from GVM minus kerb, so the figure is a calculation, not a measurement.'),
  ('toyota-tundra', 'Toyota', 'Tundra', 'full_size_pickup', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'Payload is substantially lower than vehicle size implies.'),
  ('chevrolet-silverado-1500', 'Chevrolet', 'Silverado 1500', 'full_size_pickup', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'LTZ Premium and ZR2 seeded.'),
  ('chevrolet-silverado-2500', 'Chevrolet', 'Silverado 2500 HD', 'heavy_duty_pickup', 'current', 1, 'tub_or_tray_conversion', 'seeded', 'NB1 and NB2 certification variants seeded separately.'),
  ('ram-1500', 'RAM', '1500', 'full_size_pickup', 'current', 2, 'tub_or_tray_conversion', 'seeded', 'Four Hurricane grades seeded and verified directly against the official specification brochure. The earlier unverified rows were removed after the brochure showed their Rebel and Limited figures were wrong. Outstanding: Big Horn and Laramie Night were in the earlier compilation but do not appear in this brochure.'),
  ('ram-2500', 'RAM', '2500', 'heavy_duty_pickup', 'current', 1, 'tub_or_tray_conversion', 'seeded', 'Laramie Cummins High Output seeded and verified directly against the official specification brochure.'),
  ('ram-3500', 'RAM', '3500', 'heavy_duty_pickup', 'current', 1, 'tub_or_tray_conversion', 'seeded', 'Laramie Cummins High Output seeded and verified directly, including the optional derated 4,495 kg GVM configuration recorded as its own row.'),
  ('ford-f150', 'Ford', 'F-150', 'full_size_pickup', 'current_or_limited', 2, 'tub_or_tray_conversion', 'seeded', 'Six grades seeded and verified directly against the official MY24 specification sheet across both wheelbase and box-length configurations. Outstanding: confirm whether Ford has published a detailed mass sheet newer than MY24.'),
  ('isuzu-n-series', 'Isuzu Trucks', 'N Series', 'light_truck', 'current', 1, 'truck_body', 'partially_seeded', 'NPS 75/45-155 4X4 single and crew recorded from specification sheet ARK 1443 10/21 on 4 September 2026. The rest of the N Series, and any Next Gen revision of these figures, are still outstanding.'),
  ('isuzu-nps', 'Isuzu Trucks', 'NPS 75-175 4x4', 'light_truck_4x4', 'current', 1, 'truck_body', 'seeded', 'Current day- and crew-cab chassis masses, axle limits and wheelbase seeded; body-builder approval remains mandatory.'),
  ('hino-300', 'Hino', '300 Series', 'light_truck', 'current', 2, 'truck_body', 'seeded', 'Manufacturer specification sheet HS3008174x4-0822 read on 1 September 2026. Both cab variants recorded with body length, chassis mass and axle limits.'),
  ('fuso-canter', 'Fuso', 'Canter', 'light_truck', 'current', 2, 'truck_body', 'source_identified', 'Sheets confirmed present for the 515, 615, 815 and 918. Examined 5 September 2026 and deliberately not extracted: unlike the 4x4 sheets, each 4x2 sheet covers up to six variants as lettered columns A to F, and the mass rows carry those letters rather than aligning a value to a single variant. Text extraction cannot assign a mass to a variant safely, so these need reading page by page as images. Roughly twenty combinations across the range.'),
  ('fuso-canter-4x4', 'Fuso', 'Canter 4x4', 'light_truck_4x4', 'current', 1, 'truck_body', 'seeded', 'Three FG 4x4 configurations recorded from the official Fuso variant specification sheets on 4 September 2026: wide cab SWB and MWB, and wide crew cab MWB, each with a front/rear/total mass split and 2,800/5,760 kg axle loading. The model-level row this replaces also carried the wrong torque figure, 400 Nm against the sheet''s 370 Nm. Mass is an estimate excluding fuel, so it cannot substitute for a weighbridge.'),
  ('iveco-daily-4x4', 'IVECO', 'Daily 4x4', 'light_truck_4x4', 'current', 1, 'truck_body', 'seeded', 'Six current single/crew-cab wheelbase and mass configurations seeded; engineering review remains mandatory.'),
  ('mercedes-sprinter-chassis', 'Mercedes-Benz', 'Sprinter Cab Chassis', 'van_cab_chassis', 'current', 2, 'truck_body', 'partially_seeded', 'Ten cab chassis at 5.0 and 5.5 tonnes recorded from the VS30 MY25/MY26 technical brochure on 4 September 2026. The 4.49 tonne variants are under this table CHECK (gvm_kg > 4500) and are not recorded.'),
  ('vw-crafter-chassis', 'Volkswagen', 'Crafter Cab Chassis', 'van_cab_chassis', 'current', 3, 'truck_body', 'partially_seeded', 'Four Crafter 55 recorded from the February 2021 range brochure on 4 September 2026. They cannot publish: the brochure states no model year. The Crafter 50 is 4490kg GVM, under this table CHECK (gvm_kg > 4500).'),
  ('vw-transporter', 'Volkswagen', 'Transporter', 'van', 'current_or_transitioning', 3, 'specialist_review', 'exclude_from_automatic_match', 'Not a normal removable slide-on platform; manual engineering review only.'),
  ('mercedes-unimog-u4023', 'Mercedes-Benz', 'Unimog U 4023', 'extreme_offroad_truck', 'current', 1, 'truck_body', 'partially_seeded', 'Researched 5 September 2026 and the blocker is now known rather than suspected: Mercedes-Benz publishes no kerb or unladen weight for the U 4023 anywhere, neither on the Australian page nor the extreme off-road model overview. They publish permissible total weight, 7.5/8.0/10.3 t with the corresponding special equipment, and axle loads, and stop. The 10.3 t rating and its 4.6/6.0 t axle loads are confirmed. Without a chassis mass no payload can be produced, so a weighbridge figure from an actual vehicle is the only route to publishing this row.'),
  ('mercedes-unimog-u5023', 'Mercedes-Benz', 'Unimog U 5023', 'extreme_offroad_truck', 'specialist_or_import', 2, 'specialist_review', 'source_identified', 'Researched 5 September 2026: permissible total weight 12.5/13.0/14.5 t, axle loads 5.5-6.4 t front and 7.1-8.8 t rear, wheelbase 3,850 mm, OM 934 at 170 kW and 900 Nm. As with the U 4023, Mercedes-Benz publishes no kerb weight, so no payload can be derived. Do not reuse U 4023 figures; confirm Australian supply, compliance and exact order code.'),
  ('mercedes-unimog-legacy', 'Mercedes-Benz', 'Unimog legacy / ex-service', 'extreme_offroad_truck', 'used_or_imported', 3, 'specialist_review', 'exclude_from_automatic_match', 'U 300/U 400/U 4000 and ex-service vehicles require VIN, compliance plate, weighbridge and engineering review.'),
  ('iveco-eurocargo-4x4', 'IVECO', 'Eurocargo ML150 4x4', 'medium_truck_4x4', 'current', 1, 'truck_body', 'seeded', 'Both ML150E32W wheelbases recorded from the official IVECO Australia specification sheet on 5 September 2026, with kerbweight, front/rear split and 5,700/10,000 kg axle capacities. This sheet''s kerb basis includes 180 litres of fuel, 30 litres of AdBlue and a driver, so unlike the T-Way rows the stored figure is already the conservative one.'),
  ('iveco-tway-awd', 'IVECO', 'T-Way 4x4 / 6x6 / 8x4', 'heavy_truck_awd', 'current', 2, 'truck_body', 'seeded', 'Eight variants recorded: three AD190T36W 4x4 wheelbases on 4 September 2026, then the three AD380T45W 6x6 wheelbases and the AD410T51 8x4 on 5 September 2026. The 6x6 3,800 mm column is the one place IVECO''s own arithmetic fails, and that row stores the published total without the printed axle split. At 33,500 and 41,000 kg GVM the 6x6 and 8x4 carry a slide-on many times over; the limit there is body and subframe design, not mass.'),
  ('man-tgm-4x4-rv', 'MAN', 'TGM 13.250-290 4x4 RV', 'medium_truck_4x4', 'current', 1, 'truck_body', 'seeded', 'Short- and long-cab RV chassis mass and axle data seeded from the Australian RV specification.'),
  ('man-tgs-awd', 'MAN', 'TGS 4x4 / 6x6', 'heavy_truck_awd', 'not_offered_in_australia', 2, 'specialist_review', 'exclude_from_automatic_match', 'Researched 4 September 2026 and closed: MAN Australia''s own TGS chassis availability matrix marks 4x4 and 6x6 as unavailable. Australian TGS is offered as 4x2, 6x2, 6x4 and 8x4 only. The all-wheel-drive MAN sold here is the TGM, which is already seeded. Do not reopen without evidence that MAN Australia has added an all-wheel-drive TGS.'),
  ('mercedes-arocs-awd', 'Mercedes-Benz', 'Arocs AWD', 'heavy_truck_awd', 'current_or_order_specific', 2, 'specialist_review', 'specialist_review', 'Researched 4 September 2026: the Australian Arocs page publishes cab dimensions and wheel configurations but no mass table at all, no GVM, kerb weight or axle ratings, and no downloadable Australian specification sheet. The truck is presented as configured to order and the page directs buyers to a dealer. No public source can seed this row; a dealer-supplied order-code specification is the only route.'),
  ('mercedes-zetros', 'Mercedes-Benz', 'Zetros', 'extreme_offroad_truck', 'specialist_or_import', 3, 'specialist_review', 'specialist_review', 'Availability, compliance and build specification are project-specific; never auto-match.'),
  ('scania-xt-awd', 'Scania', 'XT 4x4 / 6x6', 'heavy_truck_awd', 'current_or_order_specific', 3, 'specialist_review', 'specialist_review', 'Researched 4 September 2026: Scania Australia does list 4x4 and 6x6 XT rigids and prime movers, so the configuration is sold here, but publishes no mass or GVM for them. The one Australian XT chassis specification found, G 500 XT 6x4 rigid, gives a tare weight of 8,913 kg with tanks full of fuel and no driver at plus or minus 5 percent, but states no GVM, and it is a 6x4 rather than an all-wheel drive. This table requires a GVM, so no row can be created from it.'),
  ('volvo-fmx-awd', 'Volvo', 'FMX 4x4 / 6x6', 'heavy_truck_awd', 'current_or_order_specific', 3, 'specialist_review', 'source_identified', 'Researched 4 September 2026: the Australian FMX product overview carries engine, gearbox and cab dimension tables but no mass table of any kind. The Australian specifications page does list per-configuration data sheets, including a 6x6 rigid, but exposes them only behind view buttons rather than as retrievable URLs. Those data sheets are the source to obtain; the marketing overview is not one.'),
  ('tatra-phoenix', 'Tatra', 'Phoenix', 'extreme_offroad_truck', 'specialist_or_import', 3, 'specialist_review', 'specialist_review', 'Project-specific Australian supply and compliance; route directly to engineering.'),
  ('byd-shark-6', 'BYD', 'Shark 6', 'large_ute', 'current', 1, 'tub_or_tray_conversion', 'partially_seeded', 'One Shark 6 recorded from the BYD specification brochure. It has a coverage row only from 4 September 2026: the variant was seeded without one, so the model was invisible to anything that reads coverage rather than variants. Its 790 kg payload cannot carry a Beyond RV slide-on, and the row says so.'),
  ('mercedes-x-class', 'Mercedes-Benz', 'X-Class', 'midsize_ute', 'discontinued_used_market', 2, 'tub_or_tray_conversion', 'research_backlog', 'Sold new in Australia from April 2018 until it was axed in 2020, and still bought and converted on the used market, so it belongs in the picker. Navara-based. Figures in circulation disagree, 2,155 kg against 2,234 kg kerb for a 3,250 kg GVM, so nothing is stored: obtain the Australian specification sheet.'),
  ('mercedes-unimog-u1700l', 'Mercedes-Benz', 'Unimog U 1700 L', 'extreme_offroad_truck', 'used_or_imported', 2, 'specialist_review', 'specialist_review', 'GVM 12,000 kg, stated by the owner on 4 September 2026. Recorded here rather than as a chassis row because the sources table takes manufacturer documents only, and because a GVM alone yields no payload: a chassis mass is the missing half, and the build skips heavy chassis rows without one. Two figures circulate, 12,000 kg and an 11,000 kg off-road rating; confirm which is the plated on-road GVM. Mercedes-Benz publishes technical data for the current Unimogs only, U 4023, U 5023, U 4000 and U 5000. The U 1700 L and the whole 435 series appear only on their history pages, giving one figure, a payload of up to 5 t, with no GVM, kerb weight or axle ratings. Every Australian example is ex-service, individually plated and individually modified, so the compliance plate and a weighbridge ticket remain the figures that decide any particular vehicle.'),
  ('mercedes-atego', 'Mercedes-Benz', 'Atego', 'light_truck', 'current', 3, 'truck_body', 'research_backlog', 'Australian light and medium truck range; a plausible slide-on body platform. Variant-level mass table and body-builder data required.'),
  ('mercedes-actros', 'Mercedes-Benz', 'Actros', 'heavy_truck', 'current', 3, 'specialist_review', 'research_backlog', 'Australian heavy range. Configured to order like the Arocs, so expect no published variant mass table; route to engineering.'),
  ('chery-stockman', 'Chery', 'Stockman', 'large_ute', 'announced', 2, 'tub_or_tray_conversion', 'research_backlog', 'Named in the owners market brief of 4 September 2026 as launching by the end of 2026, a diesel plug-in hybrid. No manufacturer specification exists to seed yet. Watch for the Australian brochure, and expect the plug-in hybrid payload problem the Shark 6 row already documents.'),
  ('mg-u9', 'MG', 'U9', 'large_ute', 'current', 2, 'tub_or_tray_conversion', 'research_backlog', 'Diesel on sale in Australia now, with plug-in hybrid and electric variants flagged in the owners market brief of 4 September 2026. Australian specification sheet required.'),
  ('jac-hunter', 'JAC', 'Hunter', 'large_ute', 'current', 2, 'tub_or_tray_conversion', 'research_backlog', 'Plug-in hybrid launched in Australia per the owners market brief of 4 September 2026. Australian specification sheet required; check the payload before treating it as a slide-on platform.'),
  ('ldv-eterron', 'LDV', 'eTerron 9', 'large_ute', 'current', 2, 'tub_or_tray_conversion', 'research_backlog', 'Electric dual cab sold in Australia. Earlier in this project a set of figures for it was declined as unsourced; obtain the LDV Australia specification sheet rather than reusing them.'),
  ('gac-ute', 'GAC', 'Dual cab ute', 'large_ute', 'announced', 3, 'tub_or_tray_conversion', 'research_backlog', 'Australian launch flagged for 2027 in the owners market brief of 4 September 2026, ladder-frame, expected plug-in hybrid or range-extender. Nothing to seed until the Australian specification exists.'),
  ('mahindra-ute', 'Mahindra', 'Ladder-frame ute', 'midsize_ute', 'announced', 3, 'tub_or_tray_conversion', 'research_backlog', 'Flagged for late 2027 in the owners market brief of 4 September 2026. Model name unconfirmed; do not guess it. Nothing to seed until the Australian specification exists.');
INSERT INTO vehicle_variants VALUES
  ('ram-1500-current-listed-hurricane-range-brochure-model-year-not-stated-express-black-edition-hurricane-crew-cab-tub', 'RAM', '1500', 2026, NULL, 'Express Black Edition Hurricane', 'crew_cab', 'pickup_tub', 'part-time 4x4', '3.0L Hurricane straight-six twin-turbo petrol, standard output, 313 kW / 635 Nm', '8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3672, 2491, 'manufacturer “Kerb Weight”; brochure footnote applies manufacturer-defined kerb basis', 3505, 7711, 1770, 1860, 1014, 'manufacturer-published payload', 4500, 450, NULL, 1295, NULL, 'ram-1500-2026-au', 'Official RAM 1500 Hurricane brochure, PDF p.13 of 16, table “RAM 1500 SPECIFICATIONS”, “WEIGHTS & CAPABILITIES” and “WEIGHTS & CAPABILITIES (CONTINUED)”; cargo-tub dimensions in the same table.', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. The official current range also lists Laramie Night, which is absent from this brochure. Tub length is retained exactly as the nominal published 5''7" rather than converted to millimetres.'),
  ('ram-1500-current-listed-hurricane-range-brochure-model-year-not-stated-laramie-sport-hurricane-crew-cab-tub', 'RAM', '1500', 2026, NULL, 'Laramie Sport Hurricane', 'crew_cab', 'pickup_tub', 'on-demand 4x4', '3.0L Hurricane straight-six twin-turbo petrol, standard output, 313 kW / 635 Nm', '8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3672, 2642, 'manufacturer “Kerb Weight”; brochure footnote applies manufacturer-defined kerb basis', 3505, 7711, 1770, 1860, 863, 'manufacturer-published payload', 4500, 450, NULL, 1270, NULL, 'ram-1500-2026-au', 'Official RAM 1500 Hurricane brochure, PDF p.13 of 16, table “RAM 1500 SPECIFICATIONS”, “WEIGHTS & CAPABILITIES” and “WEIGHTS & CAPABILITIES (CONTINUED)”; cargo-tub dimensions in the same table.', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. The official current range also lists Laramie Night, which is absent from this brochure. Tub length is retained exactly as the nominal published 5''7" rather than converted to millimetres.'),
  ('ram-1500-current-listed-hurricane-range-brochure-model-year-not-stated-rebel-hurricane-crew-cab-tub', 'RAM', '1500', 2026, NULL, 'Rebel Hurricane', 'crew_cab', 'pickup_tub', 'on-demand 4x4', '3.0L Hurricane straight-six twin-turbo petrol, standard output, 313 kW / 635 Nm', '8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3672, 2612, 'manufacturer “Kerb Weight”; brochure footnote applies manufacturer-defined kerb basis', 3505, 7711, 1770, 1860, 893, 'manufacturer-published payload', 4500, 450, NULL, 1295, NULL, 'ram-1500-2026-au', 'Official RAM 1500 Hurricane brochure, PDF p.13 of 16, table “RAM 1500 SPECIFICATIONS”, “WEIGHTS & CAPABILITIES” and “WEIGHTS & CAPABILITIES (CONTINUED)”; cargo-tub dimensions in the same table.', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. The official current range also lists Laramie Night, which is absent from this brochure. Tub length is retained exactly as the nominal published 5''7" rather than converted to millimetres.'),
  ('ram-1500-current-listed-hurricane-range-brochure-model-year-not-stated-limited-hurricane-high-output-crew-cab-tub', 'RAM', '1500', 2026, NULL, 'Limited Hurricane High Output', 'crew_cab', 'pickup_tub', 'on-demand 4x4', '3.0L Hurricane straight-six twin-turbo petrol, high output, 403 kW / 707 Nm', '8-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3672, 2722, 'manufacturer “Kerb Weight”; brochure footnote applies manufacturer-defined kerb basis', 3505, 7285, 1770, 1860, 783, 'manufacturer-published payload', 4200, 420, NULL, 1270, NULL, 'ram-1500-2026-au', 'Official RAM 1500 Hurricane brochure, PDF p.13 of 16, table “RAM 1500 SPECIFICATIONS”, “WEIGHTS & CAPABILITIES” and “WEIGHTS & CAPABILITIES (CONTINUED)”; cargo-tub dimensions in the same table.', 'needs_secondary_review', 0, 'DATA CONFLICT: RAM publishes 3,505 kg GVM, 2,722 kg kerb and 782 kg payload, but 3,505 - 2,722 = 783. The derived 783 kg is stored so kerb and payload reconcile; the published 782 kg is the manufacturer figure. Confirm with RAM before customer exposure. Tub-compatible camper only unless engineered tray conversion is verified. The official current range also lists Laramie Night, which is absent from this brochure. Tub length is retained exactly as the nominal published 5''7" rather than converted to millimetres.'),
  ('ford-ranger-2026-50my-xl-single-cab-cc', 'Ford', 'Ranger', 2026, NULL, 'XL', 'single_cab', 'cab_chassis', 'RWD', '2.0L Turbo diesel, 125 kW / 405 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3270, 1738, 'Ford ''Kerb Weight'': full tank of fuel, no occupants, luggage or cargo, and the lightest possible orderable combination of factory-fit equipment; cab-chassis figures exclude tray bodies.', 3150, 6200, 1400, 1959, 1412, 'manufacturer-calculated GVM minus Ford Kerb Weight', NULL, NULL, NULL, NULL, NULL, 'ford-ranger-2026-50my-au', 'Official 2026.50MY Ranger brochure, PDF p.4, table “4x2 | XL, XLT Ranger 2026.50MY Specifications”, row group “Vehicle Masses (kg)”; kerb/payload basis in footnote on the same page.', 'needs_secondary_review', 0, 'OPTIMISTIC KERB: stored kerb mass is the lightest-orderable-equipment figure, giving the largest payload. The 2026.50MY brochure was read in full on 4 September 2026 and publishes no heavier figure: pages 17 and 21 each carry a single Kerb Weight row, footnoted as the lightest possible orderable combination of factory fit equipment. Every stored GVM and kerb mass was re-checked against it and matched. There is no conservative figure to add from this source, so this disclosure is permanent unless Ford publishes one. Published on the owner''s decision as a guide, with the basis disclosed to the customer on the calculator: Beyond RV weighs the vehicle at the factory before build and those figures decide. Replace with the heavier options figure from the 2026.50MY brochure, page 21, when a copy is to hand. Not independently verified; ford.com.au blocks automated retrieval. Manufacturer derives payload by subtracting kerb mass from GVM. Ford warns that figures are approximate and subject to individual variance; weigh the actual vehicle. Cab-chassis kerb and payload exclude tray bodies.'),
  ('ford-ranger-2026-50my-xl-super-cab-cc', 'Ford', 'Ranger', 2026, NULL, 'XL', 'super_cab', 'cab_chassis', 'RWD', '2.0L Turbo diesel, 125 kW / 405 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3270, 1850, 'Ford ''Kerb Weight'': full tank of fuel, no occupants, luggage or cargo, and the lightest possible orderable combination of factory-fit equipment; cab-chassis figures exclude tray bodies.', 3200, 6200, 1400, 1959, 1350, 'manufacturer-calculated GVM minus Ford Kerb Weight', NULL, NULL, NULL, NULL, NULL, 'ford-ranger-2026-50my-au', 'Official 2026.50MY Ranger brochure, PDF p.4, table “4x2 | XL, XLT Ranger 2026.50MY Specifications”, row group “Vehicle Masses (kg)”; kerb/payload basis in footnote on the same page.', 'needs_secondary_review', 0, 'OPTIMISTIC KERB: stored kerb mass is the lightest-orderable-equipment figure, giving the largest payload. The 2026.50MY brochure was read in full on 4 September 2026 and publishes no heavier figure: pages 17 and 21 each carry a single Kerb Weight row, footnoted as the lightest possible orderable combination of factory fit equipment. Every stored GVM and kerb mass was re-checked against it and matched. There is no conservative figure to add from this source, so this disclosure is permanent unless Ford publishes one. Published on the owner''s decision as a guide, with the basis disclosed to the customer on the calculator: Beyond RV weighs the vehicle at the factory before build and those figures decide. Replace with the heavier options figure from the 2026.50MY brochure, page 21, when a copy is to hand. Not independently verified; ford.com.au blocks automated retrieval. Manufacturer derives payload by subtracting kerb mass from GVM. Ford warns that figures are approximate and subject to individual variance; weigh the actual vehicle. Cab-chassis kerb and payload exclude tray bodies.'),
  ('ford-ranger-2026-50my-xl-double-cab-tub', 'Ford', 'Ranger', 2026, NULL, 'XL', 'double_cab', 'pickup_tub', 'RWD', '2.0L Turbo diesel, 125 kW / 405 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', 3270, 2030, 'Ford ''Kerb Weight'': full tank of fuel, no occupants, luggage or cargo, and the lightest possible orderable combination of factory-fit equipment; cab-chassis figures exclude tray bodies.', 3200, 6200, 1400, 1959, 1170, 'manufacturer-calculated GVM minus Ford Kerb Weight', NULL, NULL, 1547, 1584, NULL, 'ford-ranger-2026-50my-au', 'Official 2026.50MY Ranger brochure, PDF p.4, table “4x2 | XL, XLT Ranger 2026.50MY Specifications”, row group “Vehicle Masses (kg)”; kerb/payload basis in footnote on the same page.', 'needs_secondary_review', 0, 'OPTIMISTIC KERB: stored kerb mass is the lightest-orderable-equipment figure, giving the largest payload. The 2026.50MY brochure was read in full on 4 September 2026 and publishes no heavier figure: pages 17 and 21 each carry a single Kerb Weight row, footnoted as the lightest possible orderable combination of factory fit equipment. Every stored GVM and kerb mass was re-checked against it and matched. There is no conservative figure to add from this source, so this disclosure is permanent unless Ford publishes one. Published on the owner''s decision as a guide, with the basis disclosed to the customer on the calculator: Beyond RV weighs the vehicle at the factory before build and those figures decide. Replace with the heavier options figure from the 2026.50MY brochure, page 21, when a copy is to hand. Not independently verified; ford.com.au blocks automated retrieval. Manufacturer derives payload by subtracting kerb mass from GVM. Tub-compatible camper only unless engineered tray conversion is verified. Ford warns that figures are approximate and subject to individual variance; weigh the actual vehicle. Cab-chassis kerb and payload exclude tray bodies.'),
