  licence_class_note, mounting_architecture_note, source_id, source_locator, verification_status,
  customer_selectable, notes
) VALUES
  ('mercedes-sprinter-517-mwb-hd', 'Mercedes-Benz', 'Sprinter Cab Chassis', 2025, NULL, '517 MWB HD', 'single', '4x2', 'rear-wheel drive', 'OM654 125kW', '9G-TRONIC automatic', 3665, 5000, 7000, 1850, 3500, NULL, NULL, 2112, 2888, 'Mercedes-Benz unladen mass: the vehicle with all standard equipment, 100 percent fuel and no occupants. Payload is GVM minus unladen mass, and the sheet''s lower tare mass is deliberately not used.', NULL, NULL, NULL, 3500, 'GVM 5000kg or 5500kg exceeds a car licence in most states; confirm licence class before purchase.', 'Van cab chassis. Body and tray are fitted by a body builder to the Mercedes-Benz body and equipment mounting directives. The brochure states no maximum body length, so none is recorded.', 'mercedes-sprinter-vs30-tech-my25', 'Technical Data, Cab Chassis Euro VI, model type 90715323-AEY', 'source_verified', 0, 'Maximum body length and cab to rear axle are not stated in the brochure. The 4.49 tonne variants of the same models are not recorded here: this table holds chassis above 4500kg GVM by design.'),
