-- BYD Shark 6, read from the Australian specification brochure on 4 September
-- 2026. Recorded because a plug-in hybrid ute carries its battery in the payload:
-- 3500kg GVM less 2710kg kerb leaves 790kg, and a slide-on is 700kg to 1 tonne
-- dry. A customer needs to see that before they buy the ute, not after.
   'https://bydautomotive.com.au/brochures/BYD-SHARK-6-2025.pdf', NULL, '2026-09-04', 'manufacturer_pdf', 'AU',
   'Specification table for the Premium variant. States no model year and no definition of how kerb weight is measured.');

  id, make, model, model_year_start, model_year_end, grade, cab_type, body_type, drivetrain, engine, transmission,
  certification_category, licence_class_note, wheelbase_mm, kerb_mass_kg, kerb_mass_basis, gvm_kg, gcm_kg,
  front_gawr_kg, rear_gawr_kg, published_payload_kg, payload_basis, braked_towing_kg, towball_limit_kg,
  usable_load_length_mm, usable_load_width_mm, cab_to_rear_axle_mm, source_id, source_locator,
  verification_status, customer_selectable, notes
) VALUES
  ('byd-shark-6-premium-dual-cab-tub', 'BYD', 'Shark 6', 2025, NULL, 'Premium', 'dual', 'pickup_tub',
   'all-wheel drive', '1.5L turbo petrol plus front and rear permanent magnet motors, 321kW combined',
   'single speed reduction', NULL, NULL, 3260, 2710,
   'Not stated in the brochure. The specification table gives a kerb weight without defining what it includes.',
   3500, NULL, NULL, NULL, 790,
   'Derived as GVM minus kerb mass. The brochure publishes no payload figure.',
   2500, NULL, NULL, NULL, NULL,
   'byd-shark-6-spec-2025', 'BYD SHARK 6 SPECIFICATION table, Dimensions section',
   'needs_secondary_review', 0, 'PLUG-IN HYBRID PAYLOAD: 790kg is the whole payload, and a Beyond RV slide-on is 700kg to 1 tonne dry, so this vehicle cannot carry one once occupants, fuel and gear are counted. The battery is why: the same class of ute without one carries several hundred kilograms more. The brochure states no model year and no kerb mass basis. 2025 is taken from BYD''s own document naming (BYD-SHARK-6-2025.pdf, version 03.05C) and the 2025 ANCAP badge on its cover, not from a stated model year, which is why this row is needs_secondary_review. GCM, axle limits and tub dimensions are not published in it.');
